  cmb_espirito_de_luta: [
    { canal: "bonusAcerto", quando: "espirito_de_luta", expr: "2", duracao: "temporaria" },
    { canal: "pvTemporario", quando: "espirito_de_luta", expr: "nd", duracao: "temporaria" },
