  res_ataque_inconsequente_aprimorado: [
    { canal: "danoBonus", quando: "ataque_inconsequente", expr: "5", duracao: "temporaria" },
    { canal: "pvTemporario", quando: "ataque_inconsequente", expr: "11", duracao: "temporaria" },
