  res_adrenalina_absoluta: [
    { canal: "movimento", quando: "adrenalina_absoluta", expr: "3", duracao: "temporaria" },
    { canal: "defesa", quando: "adrenalina_absoluta", expr: "2", duracao: "temporaria" },
  ],

