/**
 * Quantos incrementos de 2 PE a Brutalidade já liberou, pelo nível de Lutador.
 *
 * ⚠ PELO ESCALONAMENTO desde 2026-09-23 (autor), como a Precisão Definitiva: o
 * degrau é efeito de habilidade, e a multiclasse conta "seu nível da
 * Multiclasse + Metade do seu Nível em outras Especializações para efeitos de
 * habilidades". Um Lutador 6 / Combatente 6 conta como Lutador 9 aqui.
 */
export function degrausBrutalidade(derived) {
  const n = nivelDeEscalonamento(derived, "lutador");
  return (n >= 8 ? 1 : 0) + (n >= 12 ? 1 : 0) + (n >= 16 ? 1 : 0) + (n >= 20 ? 1 : 0);
}

const boolDe = (v) => (v ? 1 : 0);
const intDe = (v, min, max) => Math.min(max, Math.max(min, Math.trunc(Number(v) || 0)));

/** `brutalidadePE` → `brutalidade_pe`, que é o vocabulário do DSL. */
export const varDoEstado = (id) => normalizarVariavel(id);

/**
 * O Dado de Empolgação do nível atual, em quantidade e faces (`2d6` → 2 e 6).
 * O nível 1 não tem dado. A tabela é a de afty-habilidades.
 */
export function dadoEmpolgacaoDe(nivel, aprimorada = false) {
  const tabela = aprimorada ? EMPOLGACAO_DADOS.maxima : EMPOLGACAO_DADOS.base;
  const notacao = tabela[nivel];
  if (!notacao) return { qtd: 0, faces: 0 };
  const [qtd, faces] = notacao.split("d").map(Number);
  return { qtd: qtd || 0, faces: faces || 0 };
}

/**
 * Média do Dado de Empolgação do nível atual, ARREDONDADA PARA BAIXO.
 *
 * ⚠ A MÉDIA NÃO SERVE PARA TUDO (autor, 2026-09-15): *"Empolgação Ajuste não é
 * bônus fixo. É rolagem do dado de empolgação."* O Ajuste e o Desarme somam o
 * dado numa ROLAGEM (acerto e dano), e por isso entram pelos canais de dado
 * (`dadosAtaque` e `dadosNomeados`), com `dado_empolgacao_qtd` e
 * `dado_empolgacao_faces` no contexto. A média fica para o que é NÚMERO na
 * ficha e não tem onde rolar: a Defesa do Trabalho de Pés e a RD da Esquiva.
 */
export function mediaDadoEmpolgacao(nivel, aprimorada = false) {
  const { qtd, faces } = dadoEmpolgacaoDe(nivel, aprimorada);
  if (!qtd || !faces) return 0;
  return Math.floor((qtd * (faces + 1)) / 2);
}

/**
 * Normaliza o estado da ficha. Devolve sempre o objeto inteiro, com `ativo`
 * zerando tudo: é mais simples de raciocinar do que espalhar `if (ativo)` por
 * cada expressão do catálogo.
 *
 * `params` vem do deriveAfty, porque os limites dependem da ficha e este módulo
 * não calcula ficha:
 *   • `brutalidadePE`, `brutalidadePilha` — tetos das duas faixas.
 *   • `empolgacaoMaxima` — a habilidade de 12° que troca a tabela de dados,
 *     necessária para a média sair certa.
 */
/**
 * Estados que não vêm do catálogo, e sim da FICHA: as Habilidades Únicas de item
 * marcadas como ativas, e as Técnicas de Estilo do Novo Estilo da Sombra. O
 * formato é o mesmo que as outras fontes ativas do pool exclusivo vão pedir
 * quando existirem: um Feitiço Auxiliar e um Shikigami também são instâncias, e
 * não linhas de catálogo.
 *
 * ⚠ `bool` continua sendo o padrão, mas a instância pode declarar
 * `tipo: "faixa"` com `min`/`max` próprios (2026-08-10). Quem abriu a porta foi
 * a IMBUIÇÃO das Técnicas de Estilo, que não é liga-desliga: a mesma Técnica
 * ocupa várias vagas do Domínio Simples, e a quantidade É o valor que a
 * expressão lê. O teto sai da ficha (o Nível de Aptidão em Domínio) e por isso
 * viaja no próprio extra, e não no catálogo.
 */
const listaExtras = (params) => (Array.isArray(params?.estadosExtras) ? params.estadosExtras : [])
  .filter((e) => e?.id)
  .map((e) => (["faixa", "opcao", "multi"].includes(e.tipo) ? e : { ...e, tipo: "bool" }));

export function resolveCombate(creature, params = {}) {
  const c = (creature?.combate && typeof creature.combate === "object") ? creature.combate : {};
  const ativo = !!c.ativo;
  const extras = listaExtras(params);
  // Insistência (10°): "até que realize um descanso longo, o seu nível máximo
  // de empolgação abaixa em 1". Não passa por canal porque é TETO de um estado,
  // e o estado é montado antes de o Motor rodar. Mesmo caso do brutalidadePE.
  const insistenciaUsada = !!c.insistenciaUsada;
  const empolgacaoMax = EMPOLGACAO_NIVEL_MAX - (insistenciaUsada ? 1 : 0);

  const opcaoDe = (id) => {
    const def = COMBATE_ESTADOS.find((e) => e.id === id);
    const escolhida = c[id];
    return def?.opcoes?.some((o) => o.id === escolhida) ? escolhida : null;
  };
  const dominioDe = () => {
    const ids = new Set((Array.isArray(params.dominios) ? params.dominios : []).map((d) => d.id));
    const escolhido = c.dominioAtivo;
    if (typeof escolhido === "string" && ids.has(escolhido)) return escolhido;
    if (escolhido === true) {
      if (ids.has(creature?.dominioAtivoId)) return creature.dominioAtivoId;
      if (ids.size === 1) return [...ids][0];
    }
    return null;
  };

  // Zerado é o padrão de TODO estado, e o que sai fora de combate. Vem do
  // catálogo para um estado novo não escapar da regra por esquecimento.
  const zerado = {
    ...Object.fromEntries(COMBATE_ESTADOS.map((e) => [
      e.id, e.tipo === "bool" ? false : ["opcao", "dominio"].includes(e.tipo) ? null : 0,
    ])),
    ...Object.fromEntries(extras.map((e) => [
      e.id,
      e.tipo === "faixa" ? 0
        : e.tipo === "opcao" ? null
          : e.tipo === "multi" ? []
            : e.foraCombate ? true : false,
    ])),
  };

  if (!ativo) {
    return {
      ...zerado,
      ativo: false, empolgacaoMax, dadoEmpolgacao: 0, estadosExtras: extras,
    };
  }
  const brutalidade = !!c.brutalidade;
  const empolgacao = intDe(c.empolgacao ?? 1, 1, empolgacaoMax);
  const espiritoDeLuta = !!c.espiritoDeLuta;
  // ⚠ TODA faixa precisa estar aqui. O clamp abaixo usa `tetoFaixa[e.id] ?? 0`,
  // então uma faixa ausente é aparada em ZERO e o estado nunca sai do lugar, sem
  // erro nenhum. O `max` do catálogo é só da UI, e não chega aqui.
  const tetoFaixa = {
    empolgacao: empolgacaoMax,
    brutalidadePE: params.brutalidadePE ?? 0,
    brutalidadePilha: params.brutalidadePilha ?? 0,
    resistirPE: 2,
    // "1 ponto de energia para +3 ou 2 pontos para +5": o teto é o gasto máximo.
    mentePlacida: 2,
    abates: 5,
    circularAlvos: 8,
    golpeDesfocado: 3,
    devastacaoPilha: params.devastacaoPilha ?? 0,
    precisaoPE: params.precisaoPE ?? 0,
    pistoleiroEmperrar: params.pistoleiroEmperrar ?? 0,
    ataqueConcentrado: params.ataqueConcentrado ?? 0,
    adrenalinaAtletismo: params.adrenalinaAtletismo ?? 0,
    cacadorFeiticeiros: params.cacadorFeiticeiros ?? 0,
    corpoDeAco: params.corpoDeAco ?? 0,
    cobrirSePE: params.cobrirSePE ?? 0,
    estimuloTeste: params.estimuloTeste ?? 0,
    fluxoPER: params.fluxoPER ?? 0,
    regeneracaoPE: params.regeneracaoPE ?? 0,
    conhecimentoAplicado: params.conhecimentoAplicado ?? 0,
    adeptoFeiticariaReducoesUsadas: params.adeptoFeiticariaReducoesUsadas ?? 0,
    tempestadeIdeiasUsos: params.tempestadeIdeiasUsos ?? 0,
  };
  /* ⚠ O AVISO ACIMA NÃO ERA TEÓRICO. Ao ligar o Conhecimento Aplicado em
     2026-09-07 eu declarei o `max` no catálogo, esqueci a linha aqui, e o
     contador ficou preso em zero sem erro nenhum: o efeito lia a variável, a
     variável era 0, e o bônus simplesmente não existia. O assert
     `t-estados-organiza.mjs` passou a cobrar que toda faixa tenha teto. */
  const out = { ...zerado, ativo: true, empolgacaoMax, estadosExtras: extras };
  for (const e of COMBATE_ESTADOS) {
    if (e.tipo === "bool") out[e.id] = (!e.requerApice || params.apiceId === e.requerApice) && !!c[e.id];
    else if (e.tipo === "opcao") out[e.id] = opcaoDe(e.id);
    else if (e.tipo === "dominio") out[e.id] = dominioDe();
    else {
      const min = e.min ?? 0;
      const passo = Math.max(1, Math.trunc(Number(e.passo) || 1));
      const valor = intDe(c[e.id], min, Math.max(min, tetoFaixa[e.id] ?? 0));
      out[e.id] = min + Math.floor((valor - min) / passo) * passo;
    }
  }
  for (const e of extras) {
    // O teto do extra vem PRONTO de quem o montou (a faixa de imbuição sai do
    // Nível de Aptidão em Domínio), então aqui é só aparar. Nunca é função: o
    // extra é instância da ficha, e quem o cria já enxergava a ficha inteira.
    if (e.tipo === "faixa") {
      out[e.id] = intDe(c[e.id], e.min ?? 0, Math.max(e.min ?? 0, e.max ?? 0));
    } else if (e.tipo === "opcao") {
      out[e.id] = (Array.isArray(e.opcoes) ? e.opcoes : []).some((o) => o.id === c[e.id])
        ? c[e.id]
        : null;
    } else if (e.tipo === "multi") {
      const validas = new Set((Array.isArray(e.opcoes) ? e.opcoes : []).map((o) => o.id));
      /* Um TEXTO gravado vale como lista de um: é o que um estado que era
         `opcao` deixou na sessão antes de virar `multi` (as Técnicas de Estilo,
         2026-10-11). Sem isto a escolha de antes sumia calada. */
      const cru = Array.isArray(c[e.id]) ? c[e.id] : (typeof c[e.id] === "string" && c[e.id] ? [c[e.id]] : []);
      out[e.id] = [...new Set(cru)]
        .filter((id) => validas.has(id))
        .slice(0, Math.max(0, Math.trunc(Number(e.maxSelecionados) || 0)));
    } else {
      out[e.id] = c[e.id] == null ? !!e.padrao : !!c[e.id];
    }
  }
  const surto = !!c.surtoAdrenalina;
  return {
    ...out,
    invencivelRodadas: out.invencivelSobOSol
      ? intDe(c.invencivelRodadas ?? 1, 1, 4) : 0,
    imuneCritico: !!out.invencivelSobOSol,
    imuneMovimentoForcado: !!out.invencivelSobOSol,
    // A rodada do Talismã do Ápice, para o chip da aba Buffs. Ver `afty-talisma-apice.js`.
    talismaApiceRodadas: out[ESTADO_APICE]
      ? intDe(c.talismaApiceRodadas ?? 1, 1, RODADAS_APICE) : 0,
    empolgacao,
    insistenciaUsada,
    dadoEmpolgacao: mediaDadoEmpolgacao(empolgacao, !!params.empolgacaoMaxima),
    // O dado em si, para quem ROLA em vez de somar a média.
    dadoEmpolgacaoQtd: dadoEmpolgacaoDe(empolgacao, !!params.empolgacaoMaxima).qtd,
    dadoEmpolgacaoFaces: dadoEmpolgacaoDe(empolgacao, !!params.empolgacaoMaxima).faces,
    // Os dois de Brutalidade e o upgrade do Espírito só valem com o dono ligado.
    brutalidadePE: brutalidade ? out.brutalidadePE : 0,
    brutalidadePilha: brutalidade ? out.brutalidadePilha : 0,
    espiritoIncansavel: espiritoDeLuta && !!c.espiritoIncansavel,
    // Os dois do Surto e o do Ataque Furtivo também.
    adrenalinaAbsoluta: surto && !!c.adrenalinaAbsoluta,
    adrenalinaAtletismo: surto ? out.adrenalinaAtletismo : 0,
    furtivoGarantido: !!c.ataqueFurtivo && !!c.furtivoGarantido,
  };
}

/**
 * O estado no vocabulário do DSL. Nomes em minúsculas e com underscore, igual
 * ao resto do contexto (ver buildCriaturaDslContext).
 *
 * Sai do próprio COMBATE_ESTADOS, para não haver estado sem variável. Cada
 * `opcao` rende uma booleana POR OPÇÃO (`armas_absolutas_defesa`), mais a
 * booleana do estado inteiro (`armas_absolutas`, ligada em qualquer opção):
 * assim o `quando` continua legível, sem número mágico.
 */
/**
 * ============================================================
 * AS DIVISÕES DA BANCADA
 * ============================================================
 * As sub-abas que a aba Buffs desenha, pedidas pelo autor em 2026-09-17:
 * *"Técnica | Especialização 1 | Especialização 2 | Aptidões | Interlúdio |
 * Outros"*.
 *
 * As Especializações não estão aqui porque elas saem da FICHA: uma sub-aba por
 * classe escolhida, com o nome dela, montada em `ficha-estados.js`. O que mora
 * aqui são as divisões FIXAS.
 *
 * ⚠ O id é gravado em lugar nenhum, então ele pode mudar. O `label` é o que a
 * pessoa lê na aba.
 */
export const SUB_TECNICA = { id: "tecnica", label: "Técnica" };
export const SUB_APTIDOES = { id: "aptidao", label: "Aptidões" };
export const SUB_INTERLUDIO = { id: "interludio", label: "Interlúdio" };
export const SUB_OUTROS = { id: "outros", label: "Outros" };

/** Carimba o dono numa lista de estados, sem passar por cima de quem já tem. */
export const comDonoDeBancada = (lista, dono) => (Array.isArray(lista) ? lista : [])
  .map((e) => (e?.dono ? e : { ...e, dono }));

/**
 * Uma linha da bancada deve aparecer?
 *
 * `requerEstado` sempre significou "esta linha só existe com aquela ligada", e
 * as duas telas (a bancada do criador e a aba Buffs da Ficha) repetiam a mesma
 * expressão de uma linha. Ela virou função em 2026-09-17, quando os Aliados
 * passaram a ser ESCOLHIDOS antes de graduados e o gate deixou de ser
 * booleano: a graduação do Protetor depende de `protetor` estar na lista do
 * seletor, e não de a lista ter qualquer coisa dentro.
 *
 * ⚠ LINHA COM VALOR PRÓPRIO NUNCA SOME, e essa é a regra que protege o
 * jogador: o valor de um filho não é zerado quando o pai muda, e o
 * `combateDslVars` não consulta `requerEstado` nenhum. Sem esta guarda, tirar
 * "protetor" do seletor esconderia a linha da graduação com ela ainda valendo,
 * e o bônus continuaria na ficha sem controle nenhum para desligá-lo. É o
 * mesmo motivo pelo qual uma ficha gravada antes do seletor existir continua
 * enxergando os aliados que ela já tinha.
 */
export function estadoVisivel(estado, combate = {}) {
  if (!estado?.requerEstado) return true;
  const proprio = combate[estado.id];
  if (Array.isArray(proprio) ? proprio.length > 0 : proprio) return true;
  const pai = combate[estado.requerEstado];
  if (!estado.requerOpcao) return Array.isArray(pai) ? pai.length > 0 : !!pai;
  return Array.isArray(pai) ? pai.includes(estado.requerOpcao) : pai === estado.requerOpcao;
}

export function combateDslVars(combate = {}) {
  const out = { em_combate: boolDe(combate.ativo) };
  for (const postura of POSTURA_OPCOES) {
    out[`apice_postura_${postura.id}`] = boolDe(combate.invencivelSobOSol);
  }
  for (const e of COMBATE_ESTADOS) {
    const nome = varDoEstado(e.id);
    const valor = combate[e.id];
    if (e.tipo === "faixa") {
      out[nome] = Math.max(0, Math.trunc(Number(valor) || 0));
    } else if (e.tipo === "opcao") {
      out[nome] = boolDe(valor);
      for (const o of e.opcoes) {
        out[`${nome}_${o.id}`] = boolDe(valor === o.id);
        // Slots da mesma família acendem uma booleana comum: `em_postura_sol` é
        // 1 com o Sol em QUALQUER slot, e é isso que o conteúdo lê.
        if (e.familia) {
          const comum = `em_${e.familia}_${o.id}`;
          out[comum] = boolDe(out[comum] || valor === o.id);
        }
      }
    } else {
      out[nome] = boolDe(valor);
    }
  }
  // Os estados que vieram da ficha (Habilidade Única ativa, imbuição de Técnica
  // de Estilo, e no futuro Feitiço Auxiliar e Shikigami). Entram DEPOIS do
  // catálogo: se um id colidisse com o de um estado de catálogo, quem manda é o
  // catálogo, que é o vocabulário que o conteúdo escrito à mão usa.
  for (const e of (Array.isArray(combate.estadosExtras) ? combate.estadosExtras : [])) {
    const nome = varDoEstado(e.id);
    if (nome in out) continue;
    if (e.tipo === "faixa") {
      out[nome] = Math.max(0, Math.trunc(Number(combate[e.id]) || 0));
    } else if (e.tipo === "opcao") {
      out[nome] = boolDe(combate[e.id]);
      for (const o of (Array.isArray(e.opcoes) ? e.opcoes : [])) {
        out[`${nome}_${varDoEstado(o.id)}`] = boolDe(combate[e.id] === o.id);
      }
    } else if (e.tipo === "multi") {
      // O texto de antes vale como lista de um, igual ao `resolveCombate`.
      const v = combate[e.id];
      const escolhidas = new Set(Array.isArray(v) ? v : (typeof v === "string" && v ? [v] : []));
      out[nome] = escolhidas.size;
      for (const o of (Array.isArray(e.opcoes) ? e.opcoes : [])) {
        out[`${nome}_${varDoEstado(o.id)}`] = boolDe(escolhidas.has(o.id));
      }
    } else {
      out[nome] = boolDe(combate[e.id]);
    }
  }
  // Média do Dado de Empolgação, o que as Manobras de número somam, mais o dado
  // em si, para as que ROLAM (Ajuste e Desarme).
  out.dado_empolgacao = Math.max(0, Math.trunc(Number(combate.dadoEmpolgacao) || 0));
  out.dado_empolgacao_qtd = Math.max(0, Math.trunc(Number(combate.dadoEmpolgacaoQtd) || 0));
  out.dado_empolgacao_faces = Math.max(0, Math.trunc(Number(combate.dadoEmpolgacaoFaces) || 0));
  return out;
}

/** Variáveis que o contexto expõe, para o validador de conteúdo conhecer. */
export const COMBATE_VARS = Object.keys(combateDslVars({}));

