/**
 * As categorias de tamanho, com a régua de perícia que cada uma impõe (autor,
 * 2026-08-08). Corpo grande empurra e alcança, corpo pequeno se esconde: é a
 * MESMA magnitude com o sinal trocado nas duas perícias.
 *
 * ⚠ `passo` é a distância de Médio, e é ele que o Motor move. O canal `tamanho`
 * soma degraus, e o resultado é aparado nas pontas da lista: nada abaixo de
 * Minúsculo nem acima de Colossal.
 */
export const AFTY_TAMANHOS = [
  { value: "minusculo", label: "Minúsculo", passo: -2, espacoAlcance: 1.5, atletismo: -5,  furtividade: 5 },
  { value: "pequeno",   label: "Pequeno",   passo: -1, espacoAlcance: 1.5, atletismo: -2,  furtividade: 2 },
  { value: "medio",     label: "Médio",     passo: 0,  espacoAlcance: 1.5, atletismo: 0,   furtividade: 0 },
  { value: "grande",    label: "Grande",    passo: 1,  espacoAlcance: 3,   atletismo: 2,   furtividade: -2 },
  { value: "enorme",    label: "Enorme",    passo: 2,  espacoAlcance: 4.5, atletismo: 5,   furtividade: -5 },
  { value: "colossal",  label: "Colossal",  passo: 3,  espacoAlcance: 9,   atletismo: 10,  furtividade: -10 },
];

/** O tamanho de onde toda criatura parte. Só o Motor tira ela daqui. */
export const TAMANHO_BASE = "medio";

const TAMANHO_POR_PASSO = Object.fromEntries(AFTY_TAMANHOS.map((t) => [t.passo, t]));
const PASSO_MIN = Math.min(...AFTY_TAMANHOS.map((t) => t.passo));
const PASSO_MAX = Math.max(...AFTY_TAMANHOS.map((t) => t.passo));

/**
 * A categoria que sai de `degraus` passos a partir de Médio.
 *
 * ⚠ APARA em vez de estourar: uma criatura Colossal que pegue Crescimento
 * Corporal de novo continua Colossal, e o excedente simplesmente não tem para
 * onde ir. Devolver `null` obrigaria todo chamador a tratar o caso.
 */
export function tamanhoPorDegraus(degraus = 0) {
  const passo = Math.min(PASSO_MAX, Math.max(PASSO_MIN, Math.trunc(Number(degraus) || 0)));
  return TAMANHO_POR_PASSO[passo] ?? TAMANHO_POR_PASSO[0];
}

export const getTamanho = (value) =>
  AFTY_TAMANHOS.find((t) => t.value === value) ?? TAMANHO_POR_PASSO[0];

// As origens do Afty ficam em ./afty-origens.js (catálogo de conteúdo).

/**
 * A ficha COMO ELA ESTÁ GRAVADA: o que veio do compêndio mesclado com os
 * defaults, ou a ficha em branco. Merge DEFENSIVO, para os defaults preencherem
 * lacunas de fichas antigas ou parciais sem descartar o que já existe (id, nome,
 * escolhas). Os objetos aninhados são mesclados um a um de propósito: um spread
 * raso trocaria `core` inteiro e perderia os campos que a ficha antiga não tem.
 *
 * Mora aqui, e não no criador, porque a Ficha Final precisa exatamente do mesmo
 * saneamento antes de derivar, e duas cópias divergiriam na primeira errata.
 */
export function mesclaFichaAfty(existente) {
  const blank = createBlankAfty();
  if (!existente) return blank;
  /* `periciaOficios` virou um objeto id para lista em 2026-08-30, quando o
     Ofício passou a poder se repetir na ficha. Os dois formatos antigos, a
     lista solta e o `periciaOficio` de nome único, entram como o Ofício do
     livro. Ver `oficiosDaFicha` em afty-pericias.js, que lê os três. */
  const oficiosBrutos = existente.periciaOficios;
  const listaLegado = Array.isArray(oficiosBrutos)
    ? oficiosBrutos
    : (existente.periciaOficio ? [existente.periciaOficio] : []);
  const oficios = oficiosBrutos && !Array.isArray(oficiosBrutos) && typeof oficiosBrutos === "object"
    ? oficiosBrutos
    : (listaLegado.length ? { oficio: listaLegado } : {});
  const votosExistentes = existente.votos && typeof existente.votos === "object" && !Array.isArray(existente.votos)
    ? {
      contratuais: Array.isArray(existente.votos.contratuais) ? existente.votos.contratuais : [],
      mecanicos: Array.isArray(existente.votos.mecanicos) ? existente.votos.mecanicos : [],
    }
    : null;
  const pactoLegado = existente.pacto && typeof existente.pacto === "object" && !Array.isArray(existente.pacto)
    ? existente.pacto
    : null;
  const pactoLegadoTemConteudo = !!(
    pactoLegado
    && (
      (typeof pactoLegado.nome === "string" && pactoLegado.nome.trim())
      || (typeof pactoLegado.descricao === "string" && pactoLegado.descricao.trim())
      || (Array.isArray(pactoLegado.beneficios) && pactoLegado.beneficios.length)
      || (Array.isArray(pactoLegado.maleficios) && pactoLegado.maleficios.length)
    )
  );
  const juntarLadoLegado = (lista) => ({
    texto: Array.isArray(lista)
      ? lista.map((item) => item?.texto).filter((texto) => typeof texto === "string" && texto.trim()).join("\n\n")
      : "",
    efeitos: Array.isArray(lista)
      ? lista.flatMap((item) => (Array.isArray(item?.efeitos) ? item.efeitos : []))
      : [],
  });
  const votos = votosExistentes ?? (pactoLegadoTemConteudo
    ? {
      contratuais: [],
      mecanicos: [{
        id: "voto_pacto_legado",
        nome: typeof pactoLegado.nome === "string" ? pactoLegado.nome : "",
        narrativa: typeof pactoLegado.descricao === "string" ? pactoLegado.descricao : "",
        beneficio: juntarLadoLegado(pactoLegado.beneficios),
        maleficio: juntarLadoLegado(pactoLegado.maleficios),
      }],
    }
    : blank.votos);
  return {
    ...blank,
    ...existente,
    core: { ...blank.core, ...(existente.core || {}) },
    attributes: { ...blank.attributes, ...(existente.attributes || {}) },
    attrNivel: { ...blank.attrNivel, ...(existente.attrNivel || {}) },
    attrLimite: { ...blank.attrLimite, ...(typeof existente.attrLimite === "object" ? existente.attrLimite : {}) },
    tecnicasCombate: {
      ...blank.tecnicasCombate,
      ...(existente.tecnicasCombate && typeof existente.tecnicasCombate === "object"
        ? existente.tecnicasCombate
        : {}),
      armas: Array.isArray(existente.tecnicasCombate?.armas)
        ? existente.tecnicasCombate.armas
        : [],
    },
    talentosConfig: {
      ...blank.talentosConfig,
      ...(existente.talentosConfig && typeof existente.talentosConfig === "object"
        ? existente.talentosConfig
        : {}),
      tal_mestre_das_armas: {
        ...blank.talentosConfig.tal_mestre_das_armas,
        ...(existente.talentosConfig?.tal_mestre_das_armas ?? {}),
        armas: Array.isArray(existente.talentosConfig?.tal_mestre_das_armas?.armas)
          ? existente.talentosConfig.tal_mestre_das_armas.armas
          : [],
      },
      tal_tempestade_de_ideias: {
        ...blank.talentosConfig.tal_tempestade_de_ideias,
        ...(existente.talentosConfig?.tal_tempestade_de_ideias ?? {}),
      },
      tal_artesao_amaldicoado: {
        ...blank.talentosConfig.tal_artesao_amaldicoado,
        ...(existente.talentosConfig?.tal_artesao_amaldicoado ?? {}),
      },
    },
    aptidoes: { ...blank.aptidoes, ...(existente.aptidoes || {}) },
    reducoesCustoFeitico: {
      ...blank.reducoesCustoFeitico,
      ...(existente.reducoesCustoFeitico && typeof existente.reducoesCustoFeitico === "object"
        ? existente.reducoesCustoFeitico
        : {}),
      manipulacao: Array.isArray(existente.reducoesCustoFeitico?.manipulacao)
        ? [...new Set(existente.reducoesCustoFeitico.manipulacao.filter((id) => typeof id === "string"))]
        : [],
    },
    treinoEscolhaFeiticos: existente.treinoEscolhaFeiticos && typeof existente.treinoEscolhaFeiticos === "object"
      && !Array.isArray(existente.treinoEscolhaFeiticos)
      ? Object.fromEntries(
        Object.entries(existente.treinoEscolhaFeiticos)
          .filter(([, v]) => Array.isArray(v))
          .map(([linhaId, v]) => [linhaId, [...new Set(v.filter((id) => typeof id === "string"))]]),
      )
      : {},
    // Votos são nativos e opcionais. Os Contratuais são texto sem limite; os
    // Mecânicos carregam narrativa, Benefício e Malefício. Uma ficha antiga
    // que só tenha `pacto` é convertida na leitura, sem descartar suas listas
    // de texto e efeitos.
    votos,
    // Compatibilidade rasa com a estrutura antiga. A área nativa lê `votos`,
    // mas preservar `pacto` mantém a ida e volta de fichas antigas sem perda.
    pacto: (existente.pacto && typeof existente.pacto === "object" && !Array.isArray(existente.pacto))
      ? {
        nome: typeof existente.pacto.nome === "string" ? existente.pacto.nome : "",
        descricao: typeof existente.pacto.descricao === "string" ? existente.pacto.descricao : "",
        maleficios: Array.isArray(existente.pacto.maleficios) ? existente.pacto.maleficios : [],
        beneficios: Array.isArray(existente.pacto.beneficios) ? existente.pacto.beneficios : [],
      }
      : { nome: "", descricao: "", maleficios: [], beneficios: [] },
    // ⚠ Mesma sanitização RASA do `pacto`, acima, e pelo mesmo motivo: quem lê
    // de verdade é `modificacoesCorporaisDaFicha` (afty-modificacoes-corporais.js).
    modificacoesCorporais: (existente.modificacoesCorporais && typeof existente.modificacoesCorporais === "object"
      && !Array.isArray(existente.modificacoesCorporais))
      ? {
        descricao: typeof existente.modificacoesCorporais.descricao === "string" ? existente.modificacoesCorporais.descricao : "",
        efeitosBase: Array.isArray(existente.modificacoesCorporais.efeitosBase) ? existente.modificacoesCorporais.efeitosBase : [],
        limite: Math.max(0, Math.trunc(Number(existente.modificacoesCorporais.limite) || 0)),
        enxertos: Array.isArray(existente.modificacoesCorporais.enxertos) ? existente.modificacoesCorporais.enxertos : [],
      }
      : { descricao: "", efeitosBase: [], limite: 0, enxertos: [] },
    // ⚠ Mesma sanitização RASA das duas de cima, e pelo mesmo motivo: quem lê de
    // verdade é `titaDaFicha` (afty-tita.js).
    tita: (existente.tita && typeof existente.tita === "object" && !Array.isArray(existente.tita))
      ? {
        ativo: !!existente.tita.ativo,
        membros: Math.max(1, Math.trunc(Number(existente.tita.membros) || 5)),
      }
      : { ativo: false, membros: 5 },
    formulaOverrides: { ...(existente.formulaOverrides || {}) },
    periciaOficios: oficios,
    /* ⚠ Objeto SEMPRE, mesmo vindo lixo da ficha. Uma lista ou uma string aqui
       viraria `Object.entries` de outra coisa lá no derive, e o sintoma seria
       uma perícia com atributo indefinido em vez de um erro. */
    periciaAtributoManual: (existente.periciaAtributoManual && typeof existente.periciaAtributoManual === "object"
      && !Array.isArray(existente.periciaAtributoManual))
      ? existente.periciaAtributoManual
      : {},
    // A mesma troca no TR e no ataque (2026-10-02), com a mesma guarda.
    trAtributoManual: (existente.trAtributoManual && typeof existente.trAtributoManual === "object"
      && !Array.isArray(existente.trAtributoManual))
      ? existente.trAtributoManual
      : {},
    ataqueAtributoManual: (existente.ataqueAtributoManual && typeof existente.ataqueAtributoManual === "object"
      && !Array.isArray(existente.ataqueAtributoManual))
      ? existente.ataqueAtributoManual
      : {},
    ataqueBasicoId: existente.ataqueBasicoId === "amaldicoado" ? "amaldicoado" : "corpo",
  };
}

/**
 * O nome com que uma ficha PODE ser gravada.
 *
 * ⚠ NASCEU DE UM ERRO DE IMPORTAÇÃO (2026-09-05). O importador da 2.5.2
 * (`parseImportText`, em `src/components/io-utils.js`) LANÇAVA quando achava uma
 * criatura com `name` vazio, e uma ficha sem nome derrubava o arquivo de import
 * inteiro. Desde 2026-10-03 ele dá o mesmo "Sem nome" em vez de lançar (o autor
 * escolheu o nome de reserva), então as duas pontas dizem a mesma palavra, e o
 * `asserts/t-nome-ficha.mjs` acusa se uma delas mudar sozinha.
 *
 * ⚠ MORA AQUI, E NÃO DENTRO DO `handleSave`, para o assert poder medir a mesma
 * função que o criador usa. A regra escrita em dois lugares é a regra que
 * diverge no primeiro conserto.
 *
 * "Sem nome" é a palavra que o app já usa no lugar do nome (o Preview e a lista
 * de Invocações), e não um rótulo novo.
 */
export const nomeParaGravar = (nome) => String(nome ?? "").trim() || "Sem nome";

/** Ficha Afty em branco — só ESCOLHAS, os stats são derivados. */
export function createBlankAfty() {
  return {
    system: "afty",
    rulesVersion: "afty",
    name: "",
    portraitUrl: null,
    // Ponto focal do retrato, em porcentagem (0 a 100). Vira o `object-position`
    // da imagem, para um retrato de corpo inteiro não cortar a cabeça quando o
    // banner do Preview o recorta. Mesmo campo da 2.5.2.
    portraitFocus: { x: 50, y: 50 },

    core: {
      tipo: "combatente",       // dirige coeficientes
      patamar: "comum",         // multiplica HP, escala Resistência/Atributos
      nd: 20,                   // Nível de Desafio (piso 3 na UI, → ∞ sem teto)
      // ⚠ MORTO desde 2026-08-08, e mantido só para não quebrar ficha antiga na
      // leitura: o tamanho virou DERIVADO (Médio mais o canal `tamanho` do
      // Motor). Nada lê este campo. Ver `tamanhoPorDegraus`.
      tamanho: TAMANHO_BASE,
      tecnicaAttr: "inteligencia", // atributo da Técnica (CD / RD específico)
      tecnicaDescricao: "",        // Funcionamento Básico / "Descrição da Técnica" (texto livre)
      // Efeitos do Funcionamento Básico, programados pelo jogador:
      // [{ canal, alvo?, expr }]. A técnica é ÚNICA NO MUNDO por definição, então
      // nenhum catálogo pode cobri-la: é uma das entradas do sistema em que o
      // efeito é escrito na ficha, junto dos Passivos / Características. Entra no Motor
      // por `efeitosDaTecnica`, e os filtros de estágio roteiam pelo canal, igual
      // a qualquer outra fonte. Mesmo shape do Motor das Ferramentas Amaldiçoadas.
      tecnicaEfeitos: [],
      // Funcionamentos Básicos ADICIONAIS (autor, 2026-08-12): algumas técnicas
      // entregam mais de um (o Ilimitado que também tem os Seis Olhos), e a
      // Cópia permite colocar os dos outros. Cada entrada é
      // `{ id, nome, descricao, efeitos }`, com o mesmo Motor livre do
      // principal. Os dois campos acima seguem sendo o Funcionamento Básico da
      // própria técnica, que é o primeiro da lista e não tem nome (ele É a
      // técnica). Quem junta os dois lados é `funcionamentosDaFicha`.
      funcionamentosAdicionais: [],
      // Origem. Além do `id`, guarda o que ela abre:
      //   cla             — só o Herdado se divide em clãs (`cla_gojo`...)
