    periciaAtributoManual: {},
    periciasBonus: 0,          // vagas extras vindas de fora ("+ OUTROS" da fórmula)
    resistenciasProf: {},      // { [trValue]: "treinado" | "mestre" }
    // Só no jogador (2026-09-23): o TR que a Classe inicial dá quando o livro diz
