    talentosConfig: {
      tal_mestre_das_armas: { modo: "armas", armas: [], grupo: null },
      tal_tempestade_de_ideias: { pericia: null, ferramenta: "", vantagemPericia: null },
      tal_artesao_amaldicoado: { ferramenta: null },
    },

    // ---------- SIMULAÇÃO DE COMBATE ----------
