    reducoesCustoFeitico: {
      dominancia: null,         // id do Feitiço-base escolhido
      manipulacao: [],          // ids dos Feitiços-base, até o bônus de treinamento
    },
    // Técnicas de Estilo do Novo Estilo da Sombra, o subsistema do SEM TÉCNICA
