      <TecnicaMotorEditor
        efeitos={efeitosMotor}
        onChange={(v) => onPatch({ efeitos: v })}
        pericias={pericias}
        fontesDano={fontesDano}
        dslGrupos={dslGrupos}
        invocacoes={invocacoes}
      />
    </div>
  );
}

