          <FieldLabel>Duração</FieldLabel>
          <OptionChips value={duracao} onChange={(v) => onPatch({ transfDuracao: v })} options={TRANSF_DURACOES} />
        </div>
        <div>
          <FieldLabel>Conjuração (Ação)</FieldLabel>
