      {m.resistir != null && (
        <span className="afty-rotulo text-[10px] whitespace-nowrap">
          Resistir{" "}
          <NumeroComFontes
            valor={m.resistir}
            partes={m.partesResistir}
            total={sinalDe(m.resistir)}
            className="afty-valor text-[11px]"
            ancora="direita"
            onRolar={() => rolar({ tipo: "teste", rotulo: `${m.nome} · Resistir`, bonus: m.resistir })}
          />
        </span>
      )}
    </div>
  );
}

export default function AbaAcoes({
  derived, rolar, destaque, rapido = [], abertos, onAberto, onFavorito, onRitual,
  onDesativarRitual,
  onIniciarRitualEstendido, onIniciarRitualSemTeste, onConcluirPreparacaoRitual,
  onCancelarRitual, onFinalizarRitual, onEncerrarRitual,
  onImbuir, onAtaqueBasico = null,
  adaptacao = null,
  /* ⚠ NÓ PRONTO, e não os dados da arma. Mesma forma do `adaptacao` logo acima,
     e pelo mesmo motivo: o painel mexe na SESSÃO, e a sessão é de quem monta a
     aba (a Ficha e o painel de Encontros têm `onSessao` diferentes). Assim a
     aba não precisa saber que sessão existe.

     ⚠ ELE MUDOU DE LUGAR EM 2026-09-07, a pedido do autor: *"o local aonde está
     o controle da Azamaru é meio ruim. Deixe em Ações"*. Morava no cabeçalho,
     encostado nos vitais e na Guarda, e ali disputava espaço com PV e PE sendo
     que o que ele faz é AÇÃO de combate. */
  armasTransformaveis = null,
  /* ⚠ NÓ PRONTO, pela mesma razão dos dois de cima. O Vislumbre Celeste veio
     parar aqui a pedido do autor (2026-09-09): *"para eu não precisar ir para
     Buffs o tempo inteiro"*. Descobrir os olhos é Ação Livre, e a Fadiga corre
     por turno: as duas coisas se fazem no meio da rodada. */
  bloodfeast = null, conjuracaoBloodfeast = null,
  // A Técnica Máxima: função que monta o controle de recarga de uma linha.
  controleTecnicaMaxima = null,
  /* A Expansão de Domínio (Etapa 10): função que monta o controle de mesa de
     uma linha, e o nó pronto da Exaustão de Técnica. Mesma forma da Técnica
     Máxima: quem tem a sessão é quem monta a aba. */
  controleExpansao = null,
  exaustaoTecnica = null,
  vislumbre = null,
  olhinhosLu = null,
  olhosAgulha = null,
  manipulacaoCeu = null,
  /* ⚠ NÓ PRONTO também: o montador do Golpe Especial (2026-09-24) paga PE e
     cobra o dano do Sacrifício, e isso é sessão. */
  golpeEspecial = null,
  gatilhosTreino = [], onGatilhoTreino = null,
  onArma = null, onAmpla = null, onNovoTurnoArmas = null, turnoArmas = 0, rodadaArmas = 0,
  // O contador de usos das habilidades fixadas no Rápido. Ver `ItemDeFicha`.
  contadorUsos = null,
}) {
  const dano = derived.dano?.entradas ?? [];
  const cura = derived.cura?.linhas ?? [];
  const feiticos = (derived.feiticos?.lista ?? []).filter((f) => f.tipo !== "passivo");
  const dominios = derived.dominios?.lista ?? [];
  const dominioAtivo = derived.dominios?.ativoId ?? null;
  const dominioAberto = derived.dominios?.aberta ?? null;
  const manobras = derived.testes?.manobras ?? [];
  const temRaioNegro = (derived.aptidoesEscolhidas ?? []).includes("raio_negro");
  const [modoDano, setModoDano] = useState("normal");
  const modoDanoAtivo = modoDano === "raio_negro" && !temRaioNegro ? "normal" : modoDano;
  // Crítico pendente por linha de dano. Local e não persistido: é um estado de
  // meio segundo entre o Acerto e o Dano, e guardá-lo faria a ficha reabrir
  // amanhã com um crítico de hoje engatilhado.
  const [criticos, setCriticos] = useState({});

  return (
    <div className="space-y-3">
      {adaptacao}
      {/* Antes do Rápido: os olhos mudam o custo em PE de tudo que vem abaixo. */}
      {bloodfeast}
      {vislumbre}
      {olhinhosLu}
      {olhosAgulha}
      {manipulacaoCeu}
      {/* Antes do Rápido e do Dano: reunir ou dividir é a primeira decisão da
          rodada, e ela muda a linha de dano que aparece logo abaixo. */}
      {armasTransformaveis}
      {/* Logo antes do Dano: as propriedades marcadas mudam as linhas dele. */}
      {golpeEspecial}
      {gatilhosTreino.length > 0 && (
        <div className="afty-card flex items-center gap-2 p-2">
          {gatilhosTreino.map((gatilho) => (
            <button
              key={gatilho.id}
              type="button"
              className="afty-botao text-[10px]"
              data-afty-tom={gatilho.ativo ? "destaque" : undefined}
              aria-pressed={gatilho.ativo}
              onClick={() => onGatilhoTreino?.(gatilho.id, !gatilho.ativo)}
              title={`Aplicar efeitos condicionais de ${gatilho.label}`}
            >
              {gatilho.label}
            </button>
          ))}
        </div>
      )}
      {/* ⚠ O RÁPIDO vem primeiro, antes até do Dano. Uma ficha de ND 40 tem 40
          habilidades e o jogador usa seis, e são essas seis que ele quer ver ao
          abrir a ficha. Some inteiro para quem não fixou nada. */}
      {rapido.length > 0 && (
        <Secao titulo="Rápido">
          {rapido.map((i) => (
            <ItemDeFicha
              key={i.chave}
              item={i}
              aberto={abertos.has(i.chave)}
              onAberto={onAberto}
              favorito
              onFavorito={onFavorito}
              destacado={destaque === i.chave}
              contadorUsos={contadorUsos}
            />
          ))}
        </Secao>
      )}

      {dano.length > 0 && (
        <Secao
          titulo="Dano"
          controles={(
            <>
              {onNovoTurnoArmas && <button type="button" className="afty-botao text-[10px]"
                title="Zera ataques do turno e encerra Aparar e Oscilante. Munições e emperramento permanecem."
                onClick={() => { setCriticos({}); onNovoTurnoArmas(); }}>Novo turno</button>}
              {derived.ataquesExtras > 0 && (
                <span className="afty-chip" title="Ataques Extras adicionais nesta rodada">
                  Ataques Extras <NumeroComFontes
                    valor={derived.ataquesExtras}
                    partes={derived.partes?.ataquesExtras}
                  />
                </span>
              )}
              <button
                type="button"
                className="afty-botao text-[10px]"
                data-afty-tom={modoDanoAtivo === "critico" ? "destaque" : undefined}
                aria-pressed={modoDanoAtivo === "critico"}
                onClick={() => setModoDano(modoDanoAtivo === "critico" ? "normal" : "critico")}
              >
                Crítico
              </button>
              {temRaioNegro && (
                <button
                  type="button"
                  className="afty-botao text-[10px]"
                  data-afty-tom={modoDanoAtivo === "raio_negro" ? "destaque" : undefined}
                  aria-pressed={modoDanoAtivo === "raio_negro"}
                  onClick={() => setModoDano(modoDanoAtivo === "raio_negro" ? "normal" : "raio_negro")}
                >
                  Raio Negro
                </button>
              )}
            </>
          )}
        >
          {dano.map((e) => (
            <LinhaDano
              key={(e.chaveArma ?? e.id) + ":" + turnoArmas}
              e={e}
              rolar={rolar}
              critico={!!criticos[(e.chaveArma ?? e.id) + ":" + turnoArmas]}
              onCritico={(v) => setCriticos((c) => ({ ...c, [(e.chaveArma ?? e.id) + ":" + turnoArmas]: v }))}
              destacado={destaque === `dano:${e.id}`}
              onImbuir={onImbuir}
              onAtaqueBasico={onAtaqueBasico}
              modoDano={modoDanoAtivo}
              onArma={onArma} onAmpla={onAmpla} rodadaArmas={rodadaArmas}
            />
          ))}
        </Secao>
      )}

      {cura.length > 0 && (
        <Secao titulo="Cura">
          {cura.map((l) => (
            <LinhaCura key={l.id} l={l} rolar={rolar} destacado={destaque === `cura:${l.id}`} />
          ))}
        </Secao>
      )}

      {/* A Exaustão de Técnica vem antes dos Feitiços, que ela trava (DA-16). */}
      {exaustaoTecnica}
      {feiticos.length > 0 && (
        <Secao titulo="Feitiços">
          {feiticos.map((f) => (
            <LinhaFeitico
              conjuracaoBloodfeast={conjuracaoBloodfeast}
              controleTecnicaMaxima={controleTecnicaMaxima}
              key={f.id}
              f={f}
              rolar={rolar}
              destacado={destaque === `feitico:${f.id}`}
              onRitual={onRitual}
              onDesativarRitual={onDesativarRitual}
              onIniciarRitualEstendido={onIniciarRitualEstendido}
              onIniciarRitualSemTeste={onIniciarRitualSemTeste}
              onConcluirPreparacaoRitual={onConcluirPreparacaoRitual}
              onCancelarRitual={onCancelarRitual}
              onFinalizarRitual={onFinalizarRitual}
              onEncerrarRitual={onEncerrarRitual}
              comLiberacao={derived.feiticos?.comLiberacao}
            />
          ))}
        </Secao>
      )}

      {(dominios.length > 0 || derived.dominios?.barreira?.tem || (derived.dominios?.domNivel ?? 0) > 0) && (
        <Secao titulo="Expansão de Domínio">
          <LinhaBarreiraConflito info={derived.dominios} rolar={rolar} />
          {dominios.map((d) => (
            <LinhaDominio
              key={d.id}
              d={d}
              ativo={d.id === dominioAtivo}
              fase={dominioAberto?.id === d.id ? dominioAberto.fase : null}
              partesPvDomo={derived.dominios?.barreira?.partesPvDomo}
              destacado={destaque === `dominio:${d.id}`}
              controle={controleExpansao?.(d) ?? null}
            />
          ))}
        </Secao>
      )}

      {manobras.length > 0 && (
        <Secao titulo="Outros">
          {manobras.map((m) => (
            <LinhaManobra key={m.id} m={m} rolar={rolar} destacado={destaque === `manobra:${m.id}`} />
          ))}
        </Secao>
      )}
    </div>
  );
}

import React from "react";

import { NumeroComFontes } from "../../ui/fontes";
import { sinalDe } from "../../ui/formato";
import { AFTY_ATTRS } from "../../afty-schema";
import { useDestaque } from "../usar-destaque";

/**
 * ============================================================
 * ABA PERÍCIAS — os três tipos de teste, prontos para rolar
 * ============================================================
 * Jogadas de Ataque, Testes de Resistência e Perícias. Os três somam
 * `mod do atributo + uma escala de nível + Maestria (se treinado)`, e a escala
 * NÃO é a mesma nos três: quem resolve isso é o `resolveTestes`, e aqui só se
 * exibe o número com as fontes dele.
 *
 * ⚠ Ao contrário do criador, a faixa NÃO é editável aqui. Treinar perícia é
 * escolha de ficha, e escolha mora no criador. O que a Ficha faz é rolar.
 *
 * ⚠ Os cinco TRs aparecem SEMPRE, inclusive os sem faixa, e as perícias também:
 * a regra do Preview (só quem tem faixa) serve a um resumo, e aqui o jogador
 * precisa achar a linha que ele vai rolar, mesmo sendo a que ele não treinou.
 * Quem tem faixa fica em destaque, o resto fica apagado.
 * ============================================================
 */

const ABREV = Object.fromEntries(AFTY_ATTRS.map((a) => [a.key, a.abbr]));

function LinhaTeste({ nome, atributo, bonus, textoBonus, dados, partes, prof, tag, margem, rolar, chave, destacado, falha, ataqueId }) {
  const raiz = useDestaque(destacado);
  return (
    <div
      ref={raiz}
      id={`afty-item-${chave}`}
      className="afty-linha px-2.5 py-1.5 flex items-center gap-2"
      data-afty-destacada={prof === "mestre" ? "sim" : "nao"}
      data-afty-alvo={destacado ? "sim" : undefined}
    >
      <span
        className="flex-1 min-w-0 text-[12px] font-semibold truncate"
        style={{ color: prof ? "var(--afty-texto)" : "var(--afty-texto-fraco)" }}
        title={nome}
      >
        {nome}
      </span>
      {atributo && (
        <span className="afty-rotulo text-[9px] uppercase tracking-wider flex-shrink-0">{ABREV[atributo] || ""}</span>
      )}
      {tag && <span className="afty-chip flex-shrink-0">{tag}</span>}
      {/* FALHA AUTOMÁTICA de condição (Paralisado e Inconsciente, em
          Reflexos). O número fica, porque a regra não o muda, e a marca diz
          que a rolagem não vale. Quem impôs vai no `title`. */}
      {falha?.length > 0 && (
        <span className="afty-chip flex-shrink-0" data-afty-tom="aviso" title={`Falha automática: ${falha.join(", ")}`}>
          Falha
        </span>
      )}
      {margem != null && (
        <span className="afty-rotulo font-mono tabular-nums flex-shrink-0" title="Margem de crítico">
          ({margem})
        </span>
      )}
      {/* ⚠ COM DADO A LINHA MOSTRA A ROLAGEM, e não só o fixo. A Resiliência
          pela Adrenalina soma "2d3 ao resultado", e um "+7" sozinho leria como
          se fosse tudo. A caixa alarga porque "+7 + 2d3" não cabe em 10. */}
      <NumeroComFontes
        valor={textoBonus ?? bonus}
        partes={partes}
        total={textoBonus ?? sinalDe(bonus)}
        className={`afty-valor text-[13px] text-right ${textoBonus ? "w-20" : "w-10"}`}
        ancora="direita"
        onRolar={() => rolar({ tipo: "teste", rotulo: nome, bonus, dados, margem, ataqueId })}
      />
    </div>
  );
}

/**
 * OS SEIS ATRIBUTOS.
 *
 * ⚠ Eles nunca estiveram na Ficha, e isso era um buraco: o jogador via os
 * derivados (Defesa, CD, os testes) e não via de onde eles saem. Numa mesa,
 * "faz um teste de Força pura" acontece o tempo todo.
 *
 * Mostra o VALOR grande e o modificador embaixo, porque os dois se usam: o valor
 * em pré-requisito e em regra que lê atributo, o modificador em toda conta. O
 * modificador ROLA como teste puro, e o valor não rola nada.
 *
 * ⚠ O valor exibido é o EFETIVO (`attrEff`), já com o que o Motor soma e já
 * aparado no limite. As fontes ficam no hover, como em todo número da Ficha.
 */
function Atributos({ derived, rolar }) {
  return (
    <section className="afty-card p-3">
      <h2 className="afty-card-titulo mb-2">Atributos</h2>
      <div className="grid grid-cols-3 sm:grid-cols-6 gap-1.5">
        {AFTY_ATTRS.map((a) => {
          const valor = derived.attrEff?.[a.key] ?? 0;
          const mod = derived.mods?.[a.key] ?? 0;
          return (
            <span key={a.key} className="afty-atributo" data-afty-atributo={a.key}>
              <span className="afty-atributo-rotulo" title={a.label}>{a.abbr}</span>
              <NumeroComFontes
                valor={valor}
                partes={derived.partesAtributo?.[a.key]}
                total={valor}
                formatar={false}
                className="afty-atributo-valor"
                titulo={a.label}
              />
              <NumeroComFontes
                valor={mod}
                total={sinalDe(mod)}
                className="afty-atributo-mod"
                ancora="direita"
                titulo={`Teste de ${a.label}`}
                onRolar={() => rolar({ tipo: "teste", rotulo: a.label, bonus: mod })}
              />
            </span>
          );
        })}
      </div>
    </section>
  );
}

function Secao({ titulo, children, colunas = 1 }) {
  return (
    <section className="afty-card p-3">
      <h2 className="afty-card-titulo mb-2">{titulo}</h2>
      <div className={`grid gap-1 ${colunas === 2 ? "sm:grid-cols-2" : ""}`}>{children}</div>
    </section>
  );
}

export default function AbaPericias({ derived, rolar, destaque }) {
  const { pericias = [], resistencias = [], ataques = [] } = derived.testes ?? {};

  return (
    <div className="space-y-3">
      <Atributos derived={derived} rolar={rolar} />

      {ataques.length > 0 && (
        <Secao titulo="Jogadas de Ataque" colunas={2}>
          {ataques.map((a) => (
            <LinhaTeste
              key={a.id}
              nome={a.nome}
              ataqueId={a.id}
              bonus={a.bonus}
              textoBonus={a.textoBonus}
              dados={a.dadosExtras}
              partes={a.partes}
              prof={a.treinado ? "treinado" : null}
              rolar={rolar}
              chave={`ataque:${a.id}`}
              destacado={destaque === `ataque:${a.id}`}
            />
          ))}
        </Secao>
      )}

      {resistencias.length > 0 && (
        <Secao titulo="Testes de Resistência" colunas={2}>
          {resistencias.map((r) => (
            <LinhaTeste
              key={r.value}
              nome={r.label}
              atributo={r.atributo}
              bonus={r.bonus}
              textoBonus={r.textoBonus}
              dados={r.dadosExtras}
              partes={r.partes}
              prof={r.prof}
              tag={r.prof === "mestre" ? "Mestre" : null}
              /* A margem é própria do TR. O treinamento Mestre continua
                 identificado na linha, mas não bloqueia o crítico reduzido. */
              margem={r.margemCritico}
              falha={r.falhaAutomatica}
              rolar={rolar}
              chave={`tr:${r.value}`}
              destacado={destaque === `tr:${r.value}`}
            />
          ))}
        </Secao>
      )}

      {pericias.length > 0 && (
        <Secao titulo="Perícias" colunas={2}>
          {pericias.map((p) => (
            <LinhaTeste
              key={p.id}
              nome={p.nome}
              atributo={p.atributo}
              bonus={p.bonus}
              textoBonus={p.textoBonus}
              dados={p.dadosExtras}
              partes={p.partes}
              prof={p.prof}
              tag={p.prof === "mestre" ? "Mestre" : null}
              rolar={rolar}
              chave={`pericia:${p.id}`}
              destacado={destaque === `pericia:${p.id}`}
            />
          ))}
        </Secao>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { catalogoImitacao, trocarCopiaImitacao, cdAprenderImitacao, tentarAprenderImitacao } from "../afty-imitacao";
import SubAbas from "./SubAbas";
import FiltroDeHabilidades from "../ui/FiltroDeHabilidades";
import { filtraHabilidades } from "../afty-filtro-habilidades";

const ROTULOS = { postura: "Posturas", ativa: "Habilidades ativas", passiva: "Habilidades passivas", estilo: "Estilos" };

export default function PainelDeImitacao({ derived, sessao, onPatchCombate, controleCombate }) {
  const [tipo, setTipo] = useState("postura");
  const [busca, setBusca] = useState("");
  const [efeitoFiltro, setEfeitoFiltro] = useState("todos");
  const [elegivel, setElegivel] = useState(false);
  const [resultado, setResultado] = useState("");
  const estado = sessao.combate?.imitacao ?? {};
  const tipos = derived.imitacao?.perfeita
    ? ["postura", "ativa", "passiva", "estilo"] : ["postura", "ativa"];
  const atual = tipos.includes(tipo) ? tipo : "postura";
  const lista = filtraHabilidades(catalogoImitacao(atual), efeitoFiltro, busca);
  if (!derived.imitacao?.disponivel) return null;
  const copiar = (copia) => {
    onPatchCombate(trocarCopiaImitacao(sessao.combate, copia));
    setResultado("");
  };
  const trocarTipo = (proximo) => {
    setTipo(proximo);
    setBusca("");
    setElegivel(false);
  };
  const aprender = () => {
    if (resultado.trim() === "") return;
    onPatchCombate({ imitacao: tentarAprenderImitacao(estado, Number(resultado), derived.imitacao) });
    setResultado("");
  };
  return (
    <section className="afty-card p-3 space-y-2">
      <div className="flex items-center gap-2">
        <h2 className="afty-card-titulo flex-1">{derived.imitacao.perfeita ? "Imitação Perfeita" : "Imitação"}</h2>
        {controleCombate}
      </div>
      {derived.imitacao.copia && <div className="afty-linha flex items-center gap-2 p-2">
        <span className="flex-1">{derived.imitacao.copia.nome}</span>
        <button type="button" className="afty-botao" onClick={() => copiar(null)}>Encerrar cópia</button>
      </div>}
      {derived.imitacao.copia && <div className="flex flex-wrap items-center gap-2">
        <span className="afty-chip">CD {cdAprenderImitacao(estado, estado.copia)}</span>
        <input className="afty-campo afty-linha p-2 w-28" type="number" aria-label="Resultado de Percepção" placeholder="Percepção" value={resultado} onChange={(e) => setResultado(e.target.value)} />
        <button type="button" className="afty-botao" onClick={aprender}>Tentar aprender</button>
        {estado.aviso && <span role="status" className="afty-chip">{estado.aviso}</span>}
      </div>}
      {!!estado.aprendidas?.length && <h3 className="afty-card-titulo">Aprendidas ({estado.aprendidas.length})</h3>}
      {(estado.aprendidas ?? []).map((c) => <div key={c.id} className="flex items-center gap-2">
        <button type="button" className="afty-botao flex-1 text-left" disabled={!derived.combate?.ativo || !tipos.includes(c.tipo)}
          aria-pressed={derived.imitacao.copia?.id === c.id}
          data-afty-tom={derived.imitacao.copia?.id === c.id ? "destaque" : undefined}
          title={catalogoImitacao(c.tipo).find((h) => h.id === c.id)?.descricao}
          onClick={() => copiar({ ...c })}>
          {catalogoImitacao(c.tipo).find((h) => h.id === c.id)?.nome ?? "Cópia indisponível"}
        </button>
        <button type="button" className="afty-botao" aria-label="Esquecer cópia" onClick={() => onPatchCombate({ imitacao: { ...estado, aprendidas: estado.aprendidas.filter((h) => h.id !== c.id) } })}>Esquecer</button>
      </div>)}
      <SubAbas rotulo="Tipos de cópia" ativa={atual} onAtiva={trocarTipo}
        subs={tipos.map((t) => ({ id: t, label: ROTULOS[t], quantos: filtraHabilidades(catalogoImitacao(t), efeitoFiltro, busca).length }))} />
      <FiltroDeHabilidades rotulo="Buscar cópia" efeito={efeitoFiltro} onEfeito={setEfeitoFiltro}
        termo={busca} onTermo={setBusca} visiveis={lista.length} total={catalogoImitacao(atual).length} />
      {["ativa", "passiva"].includes(atual) && <label className="flex items-center gap-2">
        <input type="checkbox" checked={elegivel} onChange={(e) => setElegivel(e.target.checked)} />
        Habilidade do tipo selecionado, sem gasto de PE
      </label>}
      <div className="max-h-64 overflow-y-auto space-y-1" role="region" aria-label="Opções de cópia">
        {lista.length === 0 && <p className="afty-vazio px-1 py-2">Nada com esse filtro</p>}
        {lista.map((h) => <button key={h.id} type="button" className="afty-linha w-full text-left p-2 disabled:opacity-40"
          disabled={!derived.combate?.ativo || (["ativa", "passiva"].includes(atual) && !elegivel)} onClick={() => copiar({ tipo: atual, id: h.id })} title={h.descricao}>
          {h.nome}
        </button>)}
      </div>
    </section>
  );
}

